<script setup>
import { onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import { collectionApi } from '@/services/collection.service'
const route=useRoute(),collection=ref(null),error=ref('')
onMounted(async()=>{try{collection.value=await collectionApi.published(route.params.slug)}catch(cause){error.value=cause.message}})
</script>
<template><section class="page-panel"><p v-if="error" class="form-error" role="alert">{{ error }}</p><div v-else-if="collection"><div class="collection-hero"><img v-if="collection.hasCover" :src="collectionApi.coverUrl(collection.slug)" alt=""><div v-else class="collection-cover-default" aria-label="ภาพปกเริ่มต้น">CSIT</div><div><p class="eyebrow">{{ collection.collectionType }} Collection</p><h1>{{ collection.name }}</h1><p>{{ collection.description }}</p><p class="material-meta">โดย @{{ collection.createdByUsername }}<span v-if="collection.courseCode"> · {{ collection.courseCode }}</span></p><RouterLink v-if="collection.documents.length" class="button button--primary" :to="`/dashboard/c/${collection.slug}/read`">เริ่มอ่านตามลำดับ</RouterLink></div></div><nav class="collection-toc" aria-label="สารบัญ"><h2>สารบัญ</h2><a v-for="section in collection.sections" :key="section.id" :href="`#section-${section.id}`">{{ section.title }}</a></nav><section v-if="collection.unsectioned.length" class="collection-section"><h2>เอกสาร</h2><RouterLink v-for="document in collection.unsectioned" :key="`${document.documentType}:${document.documentId}`" class="collection-item" :to="`/dashboard/c/${collection.slug}/read/${document.documentType.toLowerCase()}/${document.documentId}`"><strong>{{ document.title }}</strong><span>{{ document.courseCode }} · {{ document.documentType }} · @{{ document.uploaderUsername }}</span></RouterLink></section><section v-for="section in collection.sections" :id="`section-${section.id}`" :key="section.id" class="collection-section"><h2>{{ section.title }}</h2><RouterLink v-for="document in section.documents" :key="`${document.documentType}:${document.documentId}`" class="collection-item" :to="`/dashboard/c/${collection.slug}/read/${document.documentType.toLowerCase()}/${document.documentId}`"><strong>{{ document.title }}</strong><span>{{ document.courseCode }} · {{ document.documentType }} · @{{ document.uploaderUsername }}</span></RouterLink></section></div><p v-else>กำลังโหลด…</p></section></template>
